import { test } from 'vitest';
import { decodeSnapshot, SNAPSHOT_MAX_BYTES } from './snapshot.ts';
import { EXAMPLE_CODE } from './game.fixture.ts';

const SNAPSHOT = {
  version: 2,
  name: 'Café',
